package com.wayrapass.service;import com.wayrapass.dto.request.CoordinatorRequest;import com.wayrapass.dto.response.UserResponse;import com.wayrapass.exception.ConflictException;import com.wayrapass.model.*;import com.wayrapass.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class UserAdministrationService{private final UserRepository users;private final PasswordEncoder encoder;@Transactional public UserResponse createCoordinator(CoordinatorRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new ConflictException("El correo ya existe.");User u=new User();u.setFullName(r.fullName().trim());u.setEmail(r.email().trim().toLowerCase());u.setPasswordHash(encoder.encode(r.password()));u.setPhone(r.phone()==null||r.phone().isBlank()?null:r.phone().trim());u.setRole(Role.COORDINATOR);u.setEnabled(true);users.save(u);return new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getPhone(),u.getRole(),u.isEnabled(),u.getCreatedAt(),u.getUpdatedAt(),null,null);}}
